<?php
require_once __DIR__.'/../core/Guard.php';ml_guard_shield(__FILE__);if(PHP_SAPI!=='cli'){ml_guard_deny();}require_once __DIR__.'/../core/Config.php';require_once __DIR__.'/../core/Sync.php';use Core\Sync;$a=array('task'=>'hourly');$b=false;$argv=isset($argv)?$argv:array();$c=array_slice($argv,1);foreach($c as $d){if($d==='--force'){$a['force']=true;}elseif($d==='--quiet'||$d==='-q'){$b=true;}elseif($d==='--dry'){$a['dry']=true;}elseif($d==='--no-build'){$a['build']=0;}elseif($d==='--build'){$a['build']=1;}elseif(strpos($d,'--limit=')===0){$a['limit']=(int)substr($d,8);}elseif(strpos($d,'--window=')===0){$a['window']=substr($d,9);}elseif(strpos($d,'--order=')===0){$a['order']=substr($d,8);}elseif(strpos($d,'--interval=')===0){$a['interval']=(int)substr($d,11);}elseif(strpos($d,'--max-requests=')===0){$a['max_requests']=(int)substr($d,15);}elseif(strpos($d,'--sources=')===0){$e=array();foreach(explode(',',substr($d,10))as $f){$f=trim($f);if($f!==''){$e[]=$f;}}$a['sources']=$e;}elseif($d==='--help'||$d==='-h'){echo"媒资资料库 · 每小时采集\n\n";echo"用法： php cron/sync_hourly.php [选项]\n\n";echo"  --limit=20        每个源本次最多入库多少条（默认取后台设置，20）\n";echo"  --window=day      今日热榜（day|week，默认取后台设置）\n";echo"  --order=both      hot（最热）/ popular（最多人看）/ both（默认）\n";echo"  --sources=tmdb,hongguoduanju   只跑指定源（默认跑后台启用的全部源）\n";echo"  --interval=55     与上次同步的最小间隔（分钟），0 = 不限\n";echo"  --max-requests=8  单次上游请求总数硬闸\n";echo"  --force           忽略最小间隔，强制跑一次\n";echo"  --no-build        不为新增条目生成静态页\n";echo"  --dry             只探测接口、不入库\n";echo"  --quiet           只输出一行结果\n";exit(0);}}$g=Core\Config::get('sync',array());$h=(isset($g['hourly_enabled'])&&$g['hourly_enabled']!==''&&$g['hourly_enabled']!=='0'&&$g['hourly_enabled']!==0)?1:0;if(!isset($g['hourly_enabled'])||$g['hourly_enabled']===''||$g['hourly_enabled']==='1'||$g['hourly_enabled']===1){$h=1;}if(!$h){$i='每小时自动采集已关闭（后台 →「同步采集」→「每小时自动采集」开关）。本次跳过。';if($b){echo'SKIP  note='.$i."\n";}else{echo $i."\n";}exit(0);}if(!isset($a['limit'])){$j=isset($g['hourly_limit'])?(int)$g['hourly_limit']:5;$j=max(1,min(50,$j));$a['limit']=$j;}$k=Sync::run($a);if($b){echo sprintf("%s  inserted=%d skipped=%d fetched=%d requests=%d built=%d ms=%d%s\n",$k['ok']?'OK':'FAIL',(int)$k['inserted'],(int)$k['skipped_dup'],(int)$k['fetched'],(int)$k['requests'],(int)$k['built'],(int)$k['ms'],$k['reason']!==''?('  note='.$k['reason']):'');exit($k['ok']?0:1);}echo"==== 媒资资料库 · 采集开始 ".date('Y-m-d H:i:s')." ====\n";echo sprintf("参数：每源上限 %d 条 · 时间窗 %s · 口径 %s · 最低投票 %d · 重复处理 %s\n",(int)$k['params']['limit'],$k['params']['window'],$k['params']['order'],(int)$k['params']['min_votes'],$k['params']['dedupe']);echo"说明：按各源官方限制限流（TMDB 0.3s/请求、、红果短剧需配置），只取最热与最多人看的榜。\n\n";if(!empty($k['skipped'])){echo"[跳过] ".$k['reason']."\n";echo"本次未采集。（要立刻跑请加 --force）\n";exit(0);}foreach($k['sources']as $l){echo"── ".(isset($l['label'])?$l['label']:$l['source'])."\n";if($l['endpoints']){foreach($l['endpoints']as $m){echo sprintf("   · %-26s 抓到 %d 条%s\n",$m['path'],(int)$m['count'],$m['error']!==''?('   ✗ '.$m['error']):'');}}echo sprintf("   新增 %d · 重复跳过 %d · 低于票数门槛 %d · 请求 %d 次\n",(int)$l['inserted'],(int)$l['skipped_dup'],(int)$l['skipped_low'],(int)$l['requests']);if(isset($l['msg'])&&$l['msg']!==''){echo"   ⚠ ".$l['msg']."\n";}echo"\n";}echo sprintf("汇总：抓到 %d 条 → 新增 %d 条，重复跳过 %d 条，低于票数门槛 %d 条；上游请求 %d 次，静态页 %d 个，耗时 %.1fs\n",(int)$k['fetched'],(int)$k['inserted'],(int)$k['skipped_dup'],(int)$k['skipped_low'],(int)$k['requests'],(int)$k['built'],$k['ms']/1000);if($k['reason']!==''){echo"提示：".$k['reason']."\n";}if(!$k['ok']){echo"结果：失败（详见上面的提示）\n";}echo"==== 采集结束 ".date('Y-m-d H:i:s')." ====\n";exit($k['ok']?0:1);